-- ============================================================
-- Migration 013: Add Paystack columns to payments
--
-- Goal:
-- Extend the existing payments table with Paystack split-payment
-- tracking, webhook verification fields, and platform-fee
-- accounting columns. Receipts are now auto-generated by an Edge
-- Function and stored as PDF URLs; the legacy receipt_url upload
-- field is preserved but deprecated.
--
-- IMPORTANT: This migration is additive. It does NOT alter the
-- existing amount, status, or other columns the app already
-- writes. All new monetary columns are stored as INTEGER in the
-- smallest currency unit (kobo for NGN, cents for USD).
--
-- Depends on: payments table (mig 001 / COMPLETE_SETUP)
-- ============================================================

BEGIN;

-- ------------------------------------------------------------
-- 1) Add Paystack + fee columns
-- ------------------------------------------------------------
ALTER TABLE public.payments
  -- Modern monetary fields (all in smallest currency unit)
  ADD COLUMN IF NOT EXISTS dues_amount_kobo       INTEGER,                              -- amount that goes to the org
  ADD COLUMN IF NOT EXISTS platform_fee_kobo      INTEGER NOT NULL DEFAULT 0,           -- amount that goes to Payvexo
  ADD COLUMN IF NOT EXISTS total_charged_kobo     INTEGER,                              -- dues + fee actually charged
  ADD COLUMN IF NOT EXISTS currency_code          TEXT NOT NULL DEFAULT 'NGN',

  -- Paystack transaction tracking
  ADD COLUMN IF NOT EXISTS paystack_reference     TEXT,
  ADD COLUMN IF NOT EXISTS paystack_access_code   TEXT,
  ADD COLUMN IF NOT EXISTS paystack_status        TEXT,                                 -- success | failed | abandoned
  ADD COLUMN IF NOT EXISTS paystack_channel       TEXT,                                 -- card | bank | ussd | transfer | mobile_money
  ADD COLUMN IF NOT EXISTS paystack_ip_address    TEXT,
  ADD COLUMN IF NOT EXISTS paystack_fees_breakdown JSONB,                               -- raw Paystack response slice

  -- Split-payment settlement (which subaccount got the org's share)
  ADD COLUMN IF NOT EXISTS org_subaccount_code    TEXT,
  ADD COLUMN IF NOT EXISTS org_amount_settled     INTEGER,                              -- confirmed to org
  ADD COLUMN IF NOT EXISTS platform_amount_settled INTEGER,                             -- confirmed to platform

  -- Webhook verification (the source of truth for marking paid)
  ADD COLUMN IF NOT EXISTS webhook_received_at    TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS webhook_verified       BOOLEAN NOT NULL DEFAULT FALSE,
  ADD COLUMN IF NOT EXISTS webhook_signature      TEXT,
  ADD COLUMN IF NOT EXISTS webhook_attempts       INTEGER NOT NULL DEFAULT 0,

  -- Payer identity (so receipts work even if member_id is null for guest pay-for-others)
  ADD COLUMN IF NOT EXISTS payer_email            TEXT,
  ADD COLUMN IF NOT EXISTS payer_name             TEXT,
  ADD COLUMN IF NOT EXISTS user_agent             TEXT,

  -- Auto-generated receipt (replaces the receipt_url upload model)
  ADD COLUMN IF NOT EXISTS receipt_pdf_url        TEXT,
  ADD COLUMN IF NOT EXISTS receipt_generated_at   TIMESTAMPTZ,

  -- Refund tracking
  ADD COLUMN IF NOT EXISTS refunded_at            TIMESTAMPTZ,
  ADD COLUMN IF NOT EXISTS refund_reference       TEXT,
  ADD COLUMN IF NOT EXISTS refund_reason          TEXT;

-- ------------------------------------------------------------
-- 2) Constraints
-- ------------------------------------------------------------
DO $$
BEGIN
  -- paystack_reference unique (each Paystack transaction has one)
  IF NOT EXISTS (
    SELECT 1 FROM pg_indexes
    WHERE schemaname='public' AND indexname='idx_payments_paystack_ref_unique'
  ) THEN
    CREATE UNIQUE INDEX idx_payments_paystack_ref_unique
      ON public.payments (paystack_reference)
      WHERE paystack_reference IS NOT NULL;
  END IF;

  -- paystack_status check
  IF NOT EXISTS (
    SELECT 1 FROM information_schema.table_constraints
    WHERE table_schema='public' AND table_name='payments'
      AND constraint_name='chk_payments_paystack_status'
  ) THEN
    ALTER TABLE public.payments
      ADD CONSTRAINT chk_payments_paystack_status
      CHECK (paystack_status IS NULL OR paystack_status IN ('success','failed','abandoned','reversed','pending'));
  END IF;
END $$;

-- ------------------------------------------------------------
-- 3) Indexes for the new fields
-- ------------------------------------------------------------
CREATE INDEX IF NOT EXISTS idx_payments_webhook_unverified
  ON public.payments (webhook_received_at)
  WHERE webhook_verified = FALSE AND paystack_reference IS NOT NULL;

CREATE INDEX IF NOT EXISTS idx_payments_status_org_created
  ON public.payments (organization_id, status, created_at DESC);

CREATE INDEX IF NOT EXISTS idx_payments_payer_email
  ON public.payments (payer_email)
  WHERE payer_email IS NOT NULL;

-- ------------------------------------------------------------
-- 4) Backfill total_charged_kobo for existing rows
--
-- Existing payments were on the legacy receipt-upload flow with
-- no platform fee. Treat them as full-dues-no-fee transactions.
-- ------------------------------------------------------------
UPDATE public.payments
SET
  dues_amount_kobo       = ROUND(amount * 100)::INTEGER,
  total_charged_kobo     = ROUND(amount * 100)::INTEGER,
  platform_fee_kobo      = 0,
  currency_code          = COALESCE(currency_code, 'NGN')
WHERE dues_amount_kobo IS NULL AND amount IS NOT NULL;

-- ------------------------------------------------------------
-- 5) Verification
-- ------------------------------------------------------------
DO $$
DECLARE
  total INTEGER;
  with_paystack INTEGER;
  backfilled INTEGER;
BEGIN
  SELECT COUNT(*) INTO total FROM public.payments;
  SELECT COUNT(*) INTO with_paystack FROM public.payments WHERE paystack_reference IS NOT NULL;
  SELECT COUNT(*) INTO backfilled FROM public.payments WHERE dues_amount_kobo IS NOT NULL;

  RAISE NOTICE 'Migration 013 complete: payments table extended with Paystack columns.';
  RAISE NOTICE '  Total payments rows:            %', total;
  RAISE NOTICE '  Rows with paystack_reference:   %', with_paystack;
  RAISE NOTICE '  Rows backfilled to kobo:        %', backfilled;
END $$;

COMMIT;
